/* AIDM S17 Giant Rat — 12 Combat and 4 Encounter test definitions, none executed. */
USE [DnD];
GO
IF OBJECT_ID(N'Test.MonsterTestCase',N'U') IS NULL THROW 57019,'Test.MonsterTestCase missing',1;
IF NOT EXISTS(SELECT 1 FROM [Test].[MonsterTestScenario] WHERE [ScenarioCode]=N'RAT-T001') THROW 57020,'RAT-T001 missing: deploy scenario first',1;
GO
SET XACT_ABORT ON;
GO
BEGIN TRY
 BEGIN TRAN;
 DECLARE @Seed TABLE ([ScenarioCode] NVARCHAR(80) NOT NULL,[TestCaseCode] NVARCHAR(80) NOT NULL,[SequenceNo] INT NOT NULL,[TestName] NVARCHAR(180) NOT NULL,[TestPhase] NVARCHAR(40) NOT NULL,[TestStatus] NVARCHAR(20) NOT NULL,[TestRevision] INT NOT NULL,[GivenText] NVARCHAR(MAX) NOT NULL,[ExpectedText] NVARCHAR(MAX) NOT NULL,[DiceFixtureJson] NVARCHAR(MAX),[AdditionalDataJson] NVARCHAR(MAX),[LinkedStoryRef] NVARCHAR(80),[AutomatedTestRef] NVARCHAR(500),[Notes] NVARCHAR(MAX));
 INSERT INTO @Seed ([ScenarioCode],[TestCaseCode],[SequenceNo],[TestName],[TestPhase],[TestStatus],[TestRevision],[GivenText],[ExpectedText],[DiceFixtureJson],[AdditionalDataJson],[LinkedStoryRef],[AutomatedTestRef],[Notes]) VALUES
 (N'RAT-T001',N'RAT-C01',1,N'One bite per eligible Giant Rat',N'COMBAT',N'Specified',1,N'RAT-T001-1 is able to attack a valid target in a normal combat round.',N'Resolve exactly one individual bite Hit roll using the appropriate under-1-HD monster Hit table. No normal-rat pack attack or extra bite.',N'{"attack_d20":15}',N'{"attacks_per_round":1}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-C02',2,N'Successful bite inflicts 1d3 damage',N'COMBAT',N'Specified',1,N'An eligible Giant Rat hits an actual party character; damage d3=3.',N'Apply exactly 3 ordinary HP bite damage, then independently check disease on that successful bite.',N'{"attack_d20":19,"damage_d3":3,"disease_d20":8}',N'{"expected_damage":3,"expected_disease":false}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-C03',3,N'A missed bite has no secondary rolls',N'COMBAT',N'Specified',1,N'Giant Rat attack d20=1 misses a valid target.',N'Inflict no HP damage; do not roll disease chance or Saving Throw vs Poison; never mark DISEASED.',N'{"attack_d20":1}',N'{"expected_damage":0,"should_roll_disease":false,"should_roll_save":false}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-C04',4,N'Hit without disease chance has no save',N'COMBAT',N'Specified',1,N'Giant Rat hits character; bite damage d3=1, disease d20=7.',N'Apply 1 bite HP damage; no saving throw and no DISEASED because the disease check did not trigger.',N'{"damage_d3":1,"disease_d20":7}',N'{"expected_damage":1,"save_required":false,"diseased":false}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-C05',5,N'Positive disease check, saving throw passed',N'COMBAT',N'Specified',1,N'Successful bite damages Evro; disease d20=1 triggers exposure; Evro''s valid Save vs Poison succeeds under authoritative character save threshold.',N'Apply only normal bite damage; Evro remains not DISEASED; no invented disease lifecycle event.',N'{"damage_d3":2,"disease_d20":1,"poison_save_outcome":"PASS"}',N'{"target_actor":"Evro","diseased":false}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-C06',6,N'Failed poison save assigns DISEASED to Sho',N'COMBAT',N'Specified',1,N'RAT-T001-3 successfully bites Sho; d3 damage=2; disease d20=1; Sho fails their actual Save vs Poison.',N'Apply 2 normal bite HP damage and request DISEASED for Sho only; write source rat and attack event. Stop disease-specific Combat processing here.',N'{"damage_d3":2,"disease_d20":1,"poison_save_outcome":"FAIL"}',N'{"target_actor":"Sho","source_actor":"RAT-T001-3","expected_state":"DISEASED","additional_instant_disease_damage":0}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-C07',7,N'Two targets, one saved and one diseased',N'COMBAT',N'Specified',1,N'RAT-T001-1 bites Alho and RAT-T001-2 bites Evro; both independent disease d20=1; Alho saves, Evro fails.',N'Only Evro becomes DISEASED; Alho does not. Every event retains target/source identity.',N'{"disease_d20":[1,1],"poison_save_outcomes":{"Alho":"PASS","Evro":"FAIL"}}',N'{"diseased_actors":["Evro"],"not_diseased_actors":["Alho"]}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-C08',8,N'Separate disease check after every hit',N'COMBAT',N'Specified',1,N'Three separate successful Giant Rat bites occur; disease d20 faces [17,1,20].',N'Roll one independent d20 for each successful bite; only second bite proceeds to Save vs Poison. Never make one global infection roll.',N'{"disease_d20":[17,1,20]}',N'{"disease_exposure_events":1,"poison_saves_requested":1}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-C09',9,N'No immediate disease lifecycle in Combat',N'COMBAT',N'Specified',1,N'RAT-C06 has just caused an authorised DISEASED state assignment.',N'Combat does not schedule 1-6 day death, one-month bed rest, magical treatment, repeat saves, extra HP damage, instant death or imposed action penalties. State Engine future work is separate.',NULL,N'{"expected_state":"DISEASED","expected_instant_secondary_effects":0,"condition_engine_story":"AIDM-DES-017.3"}',N'AIDM-DES-001.7',NULL,N'Source-defined DISEASED lifecycle beyond the status transition belongs to separate State Engine future work.'),
 (N'RAT-T001',N'RAT-C10',10,N'Morale eight only at normally required check',N'COMBAT',N'Specified',1,N'The non-lair rat group meets an ordinary Mentzer morale check trigger.',N'Use morale 8 with standard 2d6 logic; do not add a check solely from a bite, water, fire or the image.',N'{"morale_2d6":[4,4]}',N'{"morale":8}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-C11',11,N'Giant rats do not inherit normal rat pack attack',N'COMBAT',N'Specified',1,N'Eight giant rats are adjacent to characters, each has its own actor ID.',N'Resolve attacks as independent rats, one bite each when eligible; do not aggregate into normal-rat pack damage.',NULL,N'{"rat_actor_count":8,"attack_kind":"individual bite","normal_rat_pack_attack":false}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-C12',12,N'Swimming rat can bite without invented penalty',N'COMBAT',N'Specified',1,N'A rat is swimming in shallow water with a legal target in reach.',N'Allow ordinary bite attack and 1d3 damage; swim movement 20 ft/round or 60 ft/turn. Apply no generic -1 water Hit penalty absent a verified source rule.',N'{"attack_d20":17,"damage_d3":2}',N'{"swim_round_ft":20,"swim_turn_ft":60,"innate_swim_hit_penalty":0}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-E01',13,N'Rolled count and independent HP',N'ENCOUNTER',N'Specified',1,N'Use count dice 3d6=[3,3,2] and eight independent HP d4=[3,1,4,2,2,3,1,4].',N'Create exactly eight independent giant rat actors, HP [3,1,4,2,2,3,1,4], total 20; no B1 preassigned count/HP.',N'{"count_3d6":[3,3,2],"hp_d4":[3,1,4,2,2,3,1,4]}',N'{"count":8,"total_hp":20}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-E02',14,N'One d6 surprise per side',N'ENCOUNTER',N'Specified',1,N'Party d6=5, rat side d6=2.',N'Party not surprised, rats surprised; no separate surprise per rat and no source-backed special surprise bonus.',N'{"party_d6":5,"rats_d6":2}',N'{"party_surprised":false,"rats_surprised":true}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-E03',15,N'Fire avoidance is encounter behaviour',N'ENCOUNTER',N'Specified',1,N'Uncompelled giant rats encounter a clear route away from a flaming torch.',N'Ordinarily try to withdraw/flee fire as described in Mentzer; do not assign magical FRIGHTENED state, automatic morale failure, or arbitrary numerical Hit modifier.',NULL,N'{"fire_present":true,"compelled_by_summoner":false,"extra_fear_condition":false}',N'AIDM-DES-001.7',NULL,NULL),
 (N'RAT-T001',N'RAT-E04',16,N'No mandatory hostile attack solely from art',N'ENCOUNTER',N'Specified',1,N'Rats in partially flooded dark passage notice approaching characters; one route is blocked.',N'DM/Encounter evaluates threat, defense, retreat and player intent; do not force attacks from illustration or add a lair king/leader/pack.',NULL,N'{"scene":"flooded dungeon","lair":false,"visual_reference_is_nonauthoritative":true}',N'AIDM-DES-001.7',NULL,NULL);
 INSERT INTO [Test].[MonsterTestCase] ([ScenarioCode],[TestCaseCode],[SequenceNo],[TestName],[TestPhase],[TestStatus],[TestRevision],[GivenText],[ExpectedText],[DiceFixtureJson],[AdditionalDataJson],[LinkedStoryRef],[AutomatedTestRef],[Notes])
 SELECT s.[ScenarioCode],s.[TestCaseCode],s.[SequenceNo],s.[TestName],s.[TestPhase],s.[TestStatus],s.[TestRevision],s.[GivenText],s.[ExpectedText],s.[DiceFixtureJson],s.[AdditionalDataJson],s.[LinkedStoryRef],s.[AutomatedTestRef],s.[Notes] FROM @Seed AS s
 WHERE NOT EXISTS(SELECT 1 FROM [Test].[MonsterTestCase] AS old WITH(UPDLOCK,HOLDLOCK) WHERE old.[ScenarioCode]=s.[ScenarioCode] AND old.[TestCaseCode]=s.[TestCaseCode]);
 PRINT CONCAT(N'Inserted Giant Rat test rows: ',@@ROWCOUNT);
 COMMIT;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK;
 THROW;
END CATCH;
GO
SELECT [ScenarioCode],[TestPhase],[TestStatus],COUNT(*) AS [CaseCount] FROM [Test].[MonsterTestCase] WHERE [ScenarioCode]=N'RAT-T001' GROUP BY [ScenarioCode],[TestPhase],[TestStatus] ORDER BY [TestPhase],[TestStatus];
GO
